    "explanation": "凝固点降下の「法則」と「冷却曲線」の両方を問う問題。正しいのは第2文と第4文の 2 つ。\n\n第1文は誤り。希薄溶液の凝固点降下度 Δt は Δt ＝ K_f × m（K_f：モル凝固点降下、m：質量モル濃度）で表され、溶質の種類には関係なく、溶質粒子の質量モル濃度だけで決まる（希薄溶液の束一的性質）。溶質の種類に固有なのではなく、溶媒の種類に固有なのが K_f である。「溶質の種類によらない」が凝固点降下・沸点上昇・浸透圧に共通する最大の特徴で、ここを入れ替えるのが典型的な引っかけである。\n\n第2文は正しい。電解質は水中で電離して粒子の数が増える。たとえば NaCl は Na⁺ と Cl⁻ に電離するので、同じ質量モル濃度の非電解質（スクロースなど）に比べ溶質粒子の濃度が約 2 倍になり、凝固点降下度もほぼ 2 倍になる。\n\n第3文は誤り。純溶媒が凝固する間は温度が一定に保たれるが、溶液では凝固するのは溶媒だけなので、凝固が進むにつれて残った溶液の濃度が上がり、凝固点はさらに下がっていく。冷却曲線では、純溶媒が水平になるのに対し、溶液は右下がりの直線になる。\n\n第4文は正しい。溶液では凝固中に温度が下がり続けるので、凝固し始めるときの温度を凝固点とする（実際には過冷却が起こるため、凝固が進む部分の直線を左へ延長して冷却曲線と交わる点を読み取る）。",
