    "explanation": "原子価は、その原子が他の原子とつくる共有結合の数（手の数）。CHI₃ のヨウ素原子は炭素と単結合 1 本で結びついているので原子価は 1。原子価が 1 なのは H₂ の H で、正解は①。\n\n① H₂（H–H）：H の原子価は 1。\n② H₂O₂（H–O–O–H）：各 O は H と O の 2 つの原子と結合しており原子価は 2。\n③ SiF₄：Si は 4 個の F と結合しており原子価は 4（炭素と同じ 14 族）。\n④ NH₃：N は 3 個の H と結合しており原子価は 3。非共有電子対は原子価に数えない。\n\n原子価は「8 − 価電子の数」（H は 1）で見当がつく。17 族（F・Cl・Br・I）は 1、16 族（O・S）は 2、15 族（N・P）は 3、14 族（C・Si）は 4。",
