    "explanation": "金属が十分にあるとき、発生する水素の量を決めるのは金属ではなく加えた塩酸（H⁺）の量。正解は③の直線(ウ)。\n\n反応式は 2Al ＋ 6HCl → 2AlCl₃ ＋ 3H₂、Mg ＋ 2HCl → MgCl₂ ＋ H₂。どちらも HCl 2 mol あたり H₂ 1 mol、つまり加えた HCl の物質量の半分の H₂ が発生する（H⁺ 2 個が電子 2 個を受け取って H₂ 1 分子になるので、電子を出す金属の種類によらない）。直線(ウ)は 20 mL まで折れ曲がらずに伸びているのでアルミニウムは余っており、塩酸の量が発生量を決めている。マグネシウムでも同じ塩酸が決めるので、傾きは変わらず直線(ウ)。\n\n「Al は 3 価、Mg は 2 価だから発生量が変わる」と考えてイやエを選ぶのが引っかけ。金属の価数が効くのは、金属が先に使い切られて塩酸が余る場合（グラフが水平になる位置）だけ。Mg n mol を使い切るのに要する HCl は 2n mol で Al（3n mol）より少ないので、塩酸を増やし続ければ Mg のほうが先に水平になるが、選択肢はどれも原点を通る直線なので、塩酸が決めている範囲の傾きで比べる。",
