    "question": "図のグループ C に属する最外殻電子数 8 の元素について、正しい記述の組合せを一つ選べ。\n\nA：単体の沸点は、原子番号が大きくなるほど高い。\nB：第2周期の元素は、常温・常圧で橙赤色の気体である。\nC：第4周期の元素の電子配置は、N 殻に収容される電子数がもっとも多い。\nD：第3周期の元素は、空気中の存在量（体積比）が二酸化炭素よりも小さい。\nE：単体は、原子 1 個で存在して分子のようにふるまう。",
