    "answer": 0,
    "explanation": "「グループ C（13〜18 族）に属する最外殻電子数 8 の元素」とは 18 族の貴ガスのうち第2〜4周期の Ne・Ar・Kr のことである。貴ガスの性質を 5 つの角度から確かめる問題で、正しいのは A と E。正解は①（ア）。\n\nA：貴ガスは単原子分子で、分子間には弱いファンデルワールス力しか働かない。ファンデルワールス力は分子量（原子番号）が大きいほど強くなるので、沸点は He ＜ Ne ＜ Ar ＜ Kr ＜ Xe の順に高くなる。正しい。\nB：第2周期の貴ガスはネオン Ne で、無色の気体である。ネオンサインが橙赤色に光るのは放電したときの発光で、気体そのものに色はない。誤り。\nC：第4周期の貴ガスはクリプトン Kr（原子番号 36）で、電子配置は K2 L8 M18 N8。最も多く電子が収容されているのは M 殻（18 個）で、N 殻は最外殻の 8 個である。誤り。\nD：第3周期の貴ガスはアルゴン Ar で、空気中に体積比で約 0.93 ％ 含まれ、二酸化炭素（約 0.04 ％）より多い。乾燥空気の組成は N₂ 78 ％ ＞ O₂ 21 ％ ＞ Ar 0.93 ％ ＞ CO₂ 0.04 ％ の順で、Ar が 3 番目である。誤り。\nE：貴ガスは最外殻が閉殻で安定なため、他の原子と結合せず原子 1 個で分子のようにふるまう（単原子分子）。正しい。\n\n貴ガスは「単原子分子・無色無臭・反応性に乏しい・沸点は原子番号が大きいほど高い・Ar は空気中で 3 番目に多い」の 5 点をまとめて覚える。",
