    "explanation": "金属イオンの系統分離の定番の流れで、各段階で何が沈殿し、途中の加熱・硝酸の操作が何のためかを問う問題。正解は②（イ）。\n\n順に追う。①希塩酸 → Ag⁺ だけが AgCl（白色）として沈殿する（沈殿 a）。②硫化水素（酸性条件）→ イオン化傾向の小さい Cu²⁺ が CuS（黒色）として沈殿する（沈殿 b）。このとき H₂S は還元剤なので、Fe³⁺ は Fe²⁺ に還元されてろ液 2 に残る。③ろ液 2 を加熱して溶けている H₂S を追い出し、希硝酸を加えて Fe²⁺ を Fe³⁺ に酸化し直す。④過剰のアンモニア水 → Fe³⁺ が水酸化鉄(III)（赤褐色）として沈殿する（沈殿 c）。Ca²⁺ と Li⁺ は沈殿しない。⑤炭酸アンモニウム → Ca²⁺ が CaCO₃（白色）として沈殿する（沈殿 d）。ろ液 4 には Li⁺ が残る。\n\n①：AgCl は過剰のアンモニア水に [Ag(NH₃)₂]⁺ をつくって溶ける。誤り。\n②：H₂S によって Fe³⁺ が Fe²⁺ に還元されるので、ろ液 2 には Fe²⁺ が含まれる（この反応で硫黄が遊離して液が白濁する）。正しい。\n③：沈殿 a（AgCl）と沈殿 d（CaCO₃）はどちらも白色なので「すべて異なる」は誤り。b は黒色、c は赤褐色。\n④：加熱は溶けている H₂S を除くためで、濃縮ではない。H₂S が残ったまま次の操作に進むと、塩基性にしたときに他のイオンが硫化物として沈殿してしまう。誤り。\n⑤：ろ液 4 に残るのは Li⁺ で、炎色反応は赤色。橙赤色は Ca、黄色は Na である。誤り。\n\n「H₂S を通じたあとは、加熱で H₂S を除き、硝酸で Fe²⁺ を Fe³⁺ に戻す」の 2 操作の目的は毎年のように問われる。",
