    "explanation": "まず沈殿 b の正体を決める。希塩酸で Ag⁺ を AgCl として除いたろ液 1 は酸性で、そこに硫化水素を通じて沈殿するのはイオン化傾向の小さい Cu²⁺ だけ（CuS、黒色）。したがって沈殿 b に含まれる金属は銅 Cu である。銅について 4 つの記述を判定すると、正しいのは第1文と第3文の 2 つ。\n\n第1文：銅は水素よりイオン化傾向が小さいので希塩酸や希硫酸には溶けないが、酸化力のある酸（希硝酸・濃硝酸・熱濃硫酸）には溶ける。希硝酸では 3Cu ＋ 8HNO₃ → 3Cu(NO₃)₂ ＋ 2NO ＋ 4H₂O で無色の NO が発生する。正しい。\n第2文：Cu²⁺ を含む水溶液に少量のアンモニア水（または NaOH 水溶液）を加えると、青白色の水酸化銅(II) Cu(OH)₂ が沈殿する。「緑白色」は Fe(OH)₂ の色で、銅ではない。誤り。\n第3文：Cu(OH)₂ に過剰のアンモニア水を加えると、深青色のテトラアンミン銅(II)イオン [Cu(NH₃)₄]²⁺ となって溶ける。過剰のアンモニア水で溶ける水酸化物は Cu・Ag・Zn（覚え方は「銅・銀・亜鉛」）。正しい。\n第4文：銅は熱濃硫酸に酸化され、Cu ＋ 2H₂SO₄ → CuSO₄ ＋ SO₂ ＋ 2H₂O で二酸化硫黄が発生する。SO₂ は刺激臭はあるが無色の気体なので、「有色」が誤り。有色の気体は NO₂（赤褐色）・Cl₂（黄緑色）・O₃（淡青色）で、SO₂ は入らない。誤り。\n\n「Cu(OH)₂ は青白色、Fe(OH)₂ は緑白色、Fe(OH)₃ は赤褐色」という水酸化物の色と、「SO₂ は無色・刺激臭、NO₂ は赤褐色・刺激臭」という気体の色が、そのまま正誤の決め手になる。",
