    "explanation": "発生する気体を決めてから性質を照らし合わせる。アは塩化水素 HCl、イは酸素 O₂。a〜c のすべてに当てはまるのはアだけで、正解は①。\n\nア：NaCl ＋ H₂SO₄ → NaHSO₄ ＋ HCl（揮発性の酸の遊離）。HCl は無色・刺激臭（a ○）、水によく溶けて塩酸となり強い酸性を示す（b ○）、空気より重く水に溶けるので下方置換で捕集し、上方置換は不適（c ○）。\nイ：2KClO₃ → 2KCl ＋ 3O₂（MnO₂ は触媒）。O₂ は無色・無臭なので a に当てはまらない。水に溶けにくく中性（b ×）、水上置換で捕集するので上方置換は不適（c ○）。\n\n捕集法の判断：水に溶けにくい→水上置換、水に溶けて空気より軽い（NH₃ だけ）→上方置換、水に溶けて空気より重い（HCl・Cl₂・SO₂・NO₂・H₂S・CO₂）→下方置換。",
