    "explanation": "抽出の流れから A〜D を決め、それぞれの性質を確かめる問題。最初の NaOH で水層へ移るのは酸性のフェノールと安息香酸、操作 a（CO₂）で遊離するのは炭酸より弱いフェノールなので A ＝ フェノール、残りの B ＝ 安息香酸。エーテル層側では操作 c（塩酸）で塩になって水層へ移るのはアニリンなので、エーテル層に残る C ＝ ニトロベンゼン、D ＝ アニリンである。誤っているのは（い）と（に）で、正解は⑤（オ）。\n\n（い）誤り。フェノールのヒドロキシ基はベンゼン環の電子密度を高め（オルト・パラ配向性）、置換反応をベンゼンより受けやすくする。フェノールが臭素水と常温で反応して 2,4,6-トリブロモフェノールの白色沈殿を生じるのに対し、ベンゼンの臭素化には鉄触媒が要ることが、その違いを示す。「A よりも受けやすい」は逆である。\n（ろ）正しい。トルエンを KMnO₄ で酸化すると、側鎖のメチル基が酸化されて安息香酸（B）になる。ベンゼン環は酸化されにくく側鎖だけが酸化される点が重要。\n（は）正しい。ニトロベンゼン（C）は特有のにおいをもつ淡黄色の液体で、水より重く水に溶けにくい。\n（に）誤り。アニリン（D）にさらし粉水溶液を加えると酸化されて赤紫色を呈する（アニリンの検出反応）。「水に不溶の黒色物質（アニリンブラック）」を生じるのは、硫酸酸性の二クロム酸カリウム水溶液で酸化したときである。二つの酸化剤と生成物の対応を入れ替えた引っかけ。\n（ほ）正しい。ニトロベンゼンをスズと塩酸で還元するとアニリン塩酸塩となり、NaOH 水溶液を加えるとアニリンが遊離する。C はまさに D の原料である。\n\n「さらし粉 → 赤紫色」「K₂Cr₂O₇ → 黒色のアニリンブラック」「フェノールは臭素水で白色沈殿」の 3 つは、色と試薬の組でそのまま覚える。",
