    "explanation": "C₃H₈O の 3 つの異性体を決めて性質を比べる問題。正しいのは第1・2・4文の 3 つ。\n\n同定：X は酸化でケトンになる第二級アルコール → 2-プロパノール CH₃CH(OH)CH₃。Y は水素結合をつくる（ヒドロキシ基をもつ）残りのアルコール → 1-プロパノール CH₃CH₂CH₂OH。Z はエチルメチルエーテル CH₃OCH₂CH₃。\n\n第1文：正しい。第一級アルコール Y は酸化でアルデヒド CH₃CH₂CHO を経てカルボン酸になる。\n第2文：正しい。X の酸化物アセトン CH₃COCH₃ と CH₃CH₂CHO はどちらも C₃H₆O。\n第3文：誤り。沸点は 1-プロパノール（97 ℃）＞ 2-プロパノール（82 ℃）≫ エーテル。枝分かれのある X の方が Y より低い。\n第4文：正しい。Na と反応して H₂ を出すのはヒドロキシ基をもつアルコールだけ。エーテルは反応しない。\n第5文：誤り。1 種類のアルコールの脱水縮合でできるのは R–O–R の対称エーテル（エタノールならジエチルエーテル）。エチルメチルエーテルには 2 種のアルコールが要る。\n\n「第二級 → ケトン、第一級 → アルデヒド → カルボン酸」「エーテルは Na と反応せず沸点が低い」が判定の軸。",
    "choiceNotes": [
      "誤り。正しい記述は 3 つ（第1・2・4文）ある。",
      "誤り。正しい記述は 3 つ。第1文（Y の酸化でプロピオンアルデヒド）と第2文（アセトンは C₃H₆O の異性体）に加え、第4文（Na と反応するのはアルコールだけ）も正しい。",
      "正解。X＝2-プロパノール、Y＝1-プロパノール、Z＝エチルメチルエーテル。第1・2・4文が正しく、沸点は Y ＞ X（第3文は誤り）、Z は 2 種のアルコールからしかできない（第5文は誤り）。",
      "誤り。正しい記述は 3 つ。第3文は 1-プロパノールの方が 2-プロパノールより沸点が高いので誤り。",
      "誤り。正しい記述は 3 つ。第5文は、単一アルコールの縮合では対称エーテルしかできないので誤り。"
    ],
    "verifiedAt": "2026-09-18"
