    "explanation": "完全燃焼で CO₂ と H₂O 以外のものが生じるのは、C・H・O 以外の元素を含む化合物。窒素を含むアセトアニリドと硫黄を含むベンゼンスルホン酸の 2 つで、正解は②。\n\nアセトアニリド C₆H₅–NH–CO–CH₃：アミド結合に N を含み、燃焼で N₂（や窒素酸化物）が生じる。\nベンゼンスルホン酸 C₆H₅–SO₃H：スルホ基に S を含み、燃焼で SO₂ が生じる。\nアセチルサリチル酸 C₉H₈O₄、グルコース C₆H₁₂O₆、フェノール C₆H₅OH、サリチル酸メチル C₈H₈O₃ は C・H・O だけからなるので、完全燃焼の生成物は CO₂ と H₂O のみ。\n\n名前から構成元素を思い出す：「アニリン・アニリド・アミン・アミド・ニトロ」は N、「スルホン酸・スルホ」は S、「クロロ」は Cl。",
