    "explanation": "天然ゴムと合成ゴムの製法の穴埋め。正解はウ（酢酸・乾留・シス・加硫・共重合）。\n\n(Ⅰ) ラテックスに酢酸（ギ酸）などの酸を加えるとタンパク質が凝固し、生ゴムが沈殿する。アンモニア水はラテックスが固まらないよう保存のために加えるもので、逆の役目。\n(Ⅱ) 生ゴムを乾留（空気を断って加熱分解）するとイソプレンが得られる。\n(Ⅲ) 天然ゴムのポリイソプレンの二重結合はシス形で、分子が丸まりやすく弾性を示す（トランス形はグタペルカで硬い）。\n(Ⅳ) 合成ゴムも硫黄を加えて加硫すると、鎖どうしが架橋されて弾性・強度が上がる。\n(Ⅴ) SBR はスチレンと 1,3-ブタジエンの共重合（付加重合）でつくる。\n\n「酢酸で凝固、乾留でイソプレン、シスで弾性、加硫で架橋、SBR は共重合」の 5 語をセットで覚える。",
