    "explanation": "アミノ酸の性質の正誤。正しいのは B と D で、正解はイ。\n\nA：誤り。グリシン H₂N–CH₂–COOH は不斉炭素をもたないので、L 型・D 型の区別がない。\nB：正しい。グルタミン酸はカルボキシ基を 2 つもつ酸性アミノ酸で、等電点は約 3.2 と酸性側にある。\nC：誤り。リシンは塩基性アミノ酸（等電点約 9.7）。pH 3 では陽イオンになっているので、陰極の方向に移動する。\nD：正しい。2 つのシステインの –SH が酸化されて –S–S–（ジスルフィド結合）をつくり、タンパク質の立体構造を保つ。\nE：誤り。右の図は左の図を C–COOH の結合を軸に回しただけで、同じ L-アラニンである（左は CH₃ が奥・H が手前、右は H が奥・NH₂ が手前）。鏡像異性体は鏡に映した関係で、回転しても重ならない。\n\n「等電点は酸性アミノ酸が小さく塩基性アミノ酸が大きい」「等電点より低い pH では陽イオン → 陰極へ」で判定する。",
