    "question": "正しいのはどれか。一つ選べ。\n\nA ④の鏡像異性体のうち L 型はうま味調味料として用いられる。\nB ②に水酸化ナトリウムを加えて加熱し、酢酸鉛(II) 水溶液を加えると黒色沈殿を生じる。\nC ペプチド B に固体の水酸化ナトリウムを加えて加熱するとアンモニアを生成するが、ペプチド C に同様の操作をしてもアンモニアは生成しない。\nD ペプチド B に水酸化ナトリウム水溶液と硫酸銅(II) 水溶液を加えると赤紫色を呈するが、ペプチド C に同様の操作をしても赤紫色を呈しない。",
